assert len(cases)==32
known=json.loads((out/'regression96.json').read_text(encoding='utf-8'));norm=lambda x:re.sub(r'\W+','',x.casefold())
assert not {norm(c['answer']) for c in cases}&{norm(c['answer']) for c in known}
for c in cases:
 for ok,anchors in zip(c['expected'],c['evidence_anchors']):
  assert bool(anchors)==ok
  assert all(a in c['answer'] for a in anchors)
file=out/'holdout32.json'; assert not file.exists(); file.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
freeze={'frozen_utc':datetime.now(timezone.utc).isoformat(),'sha256':hashlib.sha256(file.read_bytes()).hexdigest(),'cases':32,'new_vs_regression96':True,'evidence_oracle':'Each positive quote must contain all predeclared exact anchors for that criterion, plus author audit for semantic adequacy. This is a controlled text coverage check, not a universal entailment test.','protocol':'No inference on these cases until candidate choice is recorded. Single first pass; never tune to its failures and call it unseen. Author labels, same known four tasks; no teacher validation.'}
(out/'holdout-freeze.json').write_text(json.dumps(freeze,ensure_ascii=False,indent=2),encoding='utf-8')
